    text: "山光忽西落，池月渐东上。\n散发乘夕凉，开轩卧闲敞。\n荷风送香气，竹露滴清响。\n欲取鸣琴弹，恨无知音赏。\n感此怀故人，中宵劳梦想。",
    translation: "山上的日色忽然向西落下，池上的月亮渐渐从东边升起。我披散开头发乘着傍晚的凉意，打开窗户闲适地躺卧在敞亮的屋中。荷风送来阵阵香气，竹叶上的露水滴落发出清脆的声响。想取出琴来弹奏，可惜没有知音来欣赏。感念于此，怀念起老朋友，半夜里还在梦中苦苦思念。",
    translationSource: "public-domain",
