    author: "王昌龄",
    gradeGroup: "卷一 五言古诗",
    text: "高卧南斋时，开帷月初吐。\n清辉澹水木，演漾在窗户。\n荏苒几盈虚，澄澄变今古。\n美人清江畔，是夜越吟苦。\n千里其如何，微风吹兰杜。",
    translation: "高卧在南斋的时候，拉开帷幕看见月亮刚刚升起。清辉淡淡地洒在水面与树木上，荡漾着映在窗户之间。时光荏苒，月亮几度圆缺，澄澈的月色变换着古今。我所思念的人在清江之畔，今夜他一定在越地苦苦吟咏。相隔千里又能怎样呢，微风吹送着兰草杜若的芳香。",
    translationSource: "public-domain",
