    gradeGroup: "卷一 五言古诗",
    text: "清溪深不测，隐处唯孤云。\n松际露微月，清光犹为君。\n茅亭宿花影，药院滋苔纹。\n余亦谢时去，西山鸾鹤群。",
    translation: "清清的溪水深不可测，隐居之处只有一片孤云。松林间露出淡淡的月亮，清朗的月光仿佛还在为你而照。茅亭里停宿着花的影子，种药的院子里滋生了青苔的纹路。我也要辞别时俗而去，到西山与鸾鹤为群。",
