    title: "初发扬子寄元大校书",
    source: "《唐诗三百首》",
    dynasty: "唐",
    author: "韦应物",
    gradeGroup: "卷一 五言古诗",
    text: "凄凄去亲爱，泛泛入烟雾。\n归棹洛阳人，残钟广陵树。\n今朝此为别，何处还相遇。\n世事波上舟，沿洄安得住。",
    translation: "凄凄然地离开亲爱的人，飘飘荡荡驶进烟雾之中。我这是要乘船回洛阳去的人，耳边还萦绕着广陵树影传来的残钟声。今天在这里与你分别，何处才能再相逢。世事就像波涛上的小船，顺流逆流哪里能停得住。",
