    gradeGroup: "卷一 五言古诗",
    text: "客从东方来，衣上灞陵雨。\n问客何为来，采山因买斧。\n冥冥花正开，飏飏燕新乳。\n昨别今已春，鬓丝生几缕。",
    translation: "客人从东方来，衣上还带着灞陵的雨痕。我问客人为何而来，他说要为开山采薪来买斧头。花在幽暗中正开着，燕子翩翩飞舞，雏燕刚刚育出。上次分别到如今已是春天，你两鬓又添了几缕白发呢。",
