    dynasty: "唐",
    author: "韦应物",
    gradeGroup: "卷一 五言古诗",
    text: "落帆逗淮镇，停舫临孤驿。\n浩浩风起波，冥冥日沉夕。\n人归山郭暗，雁下芦洲白。\n独夜忆秦关，听钟未眠客。",
    translation: "落下风帆停泊在淮水边的城镇，停船靠近一座孤零零的驿站。浩浩荡荡的风掀起波浪，天色昏暗太阳沉入暮色。人们回到山边的城郭，暮色四合；大雁飞落芦洲，一片银白。孤独的夜里思念着秦关故土，我是个听着钟声难以入眠的旅人。",
