    source: "《唐诗三百首》",
    dynasty: "唐",
    author: "李白",
    gradeGroup: "卷二 七言古诗",
    text: "风吹柳花满店香，吴姬压酒唤客尝。\n金陵子弟来相送，欲行不行各尽觞。\n请君试问东流水，别意与之谁短长。",
    translation: "风吹着柳花，满店都是香气，吴地的姑娘压出酒来招呼客人品尝。金陵的子弟们前来相送，要走未走之间各自饮尽杯中的酒。请你问问那向东流去的江水，这离别的深情与它相比谁短谁长。",
