    dynasty: "唐",
    author: "李白",
    gradeGroup: "卷三 五言乐府",
    text: "长安一片月，万户捣衣声。\n秋风吹不尽，总是玉关情。\n何日平胡虏，良人罢远征。",
    translation: "长安城里一片月光，千家万户传来捣衣的声音。秋风吹不尽，总是牵挂着玉门关外的人。什么时候能扫平胡虏，让我的丈夫停止远征。",
