    text: "卢家少妇郁金堂，海燕双栖玳瑁梁。\n九月寒砧催木叶，十年征戍忆辽阳。\n白狼河北音书断，丹凤城南秋夜长。\n谁为含愁独不见，更教明月照流黄。",
    translation: "卢家少妇住在郁金香熏的堂屋里，海燕双双栖息在玳瑁装饰的梁上。九月里寒砧声催落树叶，十年的征战戍守令人思念辽阳。白狼河北书信断绝，丹凤城南的秋夜漫长。是谁让这含愁的人独自不见，又让明月照着她机上的流黄锦。",
