    text: "夫子何为者，栖栖一代中。\n地犹鄹邑，宅即鲁王宫。\n叹凤嗟身否，伤麟怨道穷。\n今看两楹奠，当与梦时同。",
    translation: "孔夫子是怎样的人呢，一生奔波忙碌、栖栖遑遑。他的出生地如今还是鄹邑，他的旧宅就是鲁王的宫殿。他曾叹息凤鸟不至、感伤自身不遇，又为麒麟被获而哀怨道之不行。如今看他受两楹之奠的祭祀，应当与他梦中的情景相同。",
