    author: "常建",
    gradeGroup: "卷五 五言律诗",
    text: "清晨入古寺，初日照高林。\n曲径通幽处，禅房花木深。\n山光悦鸟性，潭影空人心。\n万籁此俱寂，惟闻钟磬音。",
