    translation: "思乡之心在新年更加迫切，天涯边上独自泪流。年老却位居人下，春天归去比我这客子还早。与岭上的猿猴同度早晚，与江边的柳树共受风烟。我已经像被贬长沙的贾谊，从今往后又要几年。",
