    author: "钱起",
    gradeGroup: "卷五 五言律诗",
    text: "上国随缘住，来途若梦行。\n浮天沧海远，去世法舟轻。\n水月通禅寂，鱼龙听梵声。\n惟怜一灯影，万里眼中明。",
    translation: "你随缘在上国居住，来时的路途像梦一样。沧海浮天多么遥远，你离世乘坐的法舟轻快。水月通达禅寂之境，鱼龙也来听你诵经的声音。只怜那一盏孤灯的光影，在万里之外也照得眼中明亮。",
