    title: "章台夜思",
    source: "《唐诗三百首》",
    dynasty: "唐",
    author: "韦庄",
    gradeGroup: "卷五 五言律诗",
    text: "清瑟怨遥夜，绕弦风雨哀。\n孤灯闻楚角，残月下章台。\n芳草已云暮，故人殊未来。\n乡书不可寄，秋雁又南回。",
    translation: "清瑟哀怨地响在长夜，绕着琴弦是风雨般的悲声。孤灯下听到楚地的号角，残月沉下章台。芳草已经衰暮，老朋友却始终不来。家书无法寄出，秋雁又向南飞回。",
