    dynasty: "唐",
    author: "王维",
    gradeGroup: "卷六 七言律诗",
    text: "绛帻鸡人报晓筹，尚衣方进翠云裘。\n九天阊阖开宫殿，万国衣冠拜冕旒。\n日色才临仙掌动，香烟欲傍衮龙浮。\n朝罢须裁五色诏，佩声归到凤池头。",
    translation: "戴红巾的鸡人报出晓筹，尚衣官刚进上翠云裘。九天的宫门大开，万国的使臣朝拜天子。日色刚照到仙掌、光影闪动，香烟仿佛傍着龙袍浮动。朝罢还要起草五色诏书，玉佩声中回到凤凰池。",
