    gradeGroup: "卷六 七言律诗",
    text: "洞门高阁霭余晖，桃李阴阴柳絮飞。\n禁里疏钟官舍晚，省中啼鸟吏人稀。\n晨摇玉佩趋金殿，夕奉天书拜琐闱。\n强欲从君无那老，将因卧病解朝衣。",
    translation: "洞门高阁笼罩着落日的余晖，桃李浓荫、柳絮纷飞。宫禁里钟声稀疏、官舍已晚，省中鸟啼、吏人稀少。早晨玉佩摇动着快步走上金殿，傍晚捧着天子的诏书拜谢宫门。很想跟随你却无奈年老，将要因为卧病而脱下朝衣。",
    translationSource: "public-domain",
