    author: "杜甫",
    gradeGroup: "卷六 七言律诗",
    text: "清秋幕府井梧寒，独宿江城蜡炬残。\n永夜角声悲自语，中天月色好谁看。\n风尘荏苒音书绝，关塞萧条行路难。\n已忍伶俜十年事，强移栖息一枝安。",
    translation: "清秋的幕府里井边梧桐生寒，独自宿在江城、蜡炬将要烧残。长夜的角声悲凉、仿佛自言自语，中天的月色虽好又有谁看。风尘荏苒、音书断绝，关塞萧条、行路艰难。已忍受伶俜漂泊十年的往事，勉强迁就栖息、求得一枝之安。",
