    author: "杜甫",
    gradeGroup: "卷六 七言律诗",
    text: "岁暮阴阳催短景，天涯霜雪霁寒宵。\n五更鼓角声悲壮，三峡星河影动摇。\n野哭千家闻战伐，夷歌数处起渔樵。\n卧龙跃马终黄土，人事音书漫寂寥。",
    translation: "岁暮时日月催逼着短促的光阴，天涯的霜雪在寒夜放晴。五更的鼓角声悲壮，三峡的星河倒影摇动。野外的哭声千家里传来，是听到了战伐的消息；夷人的歌声几处响起，来自渔夫樵夫。卧龙诸葛亮与跃马的公孙述终究都成了黄土，人事与音书都徒然寂寥。",
