    author: "杜甫",
    gradeGroup: "卷六 七言律诗",
    text: "群山万壑赴荆门，生长明妃尚有村。\n一去紫台连朔漠，独留青冢向黄昏。\n画图省识春风面，环佩空归夜月魂。\n千载琵琶作胡语，分明怨恨曲中论。",
    translation: "群山万壑奔赴荆门，王昭君生长的村庄至今还在。她一离开汉宫就远赴塞北沙漠，只留下一座青冢对着黄昏。凭图画哪里能认识她春风般的面容，环佩叮当、空自归来的只有夜月下的魂。千载以来琵琶弹着胡地的曲调，分明是怨恨在曲中诉说。",
    translationSource: "public-domain",
