    gradeGroup: "卷六 七言律诗",
    text: "蜀主窥吴幸三峡，崩年亦在永安宫。\n翠华想像空山里，玉殿虚无野寺中。\n古庙杉松巢水鹤，岁时伏腊走村翁。\n武侯祠堂常邻近，一体君臣祭祀同。",
    translation: "蜀主刘备窥视东吴、亲临三峡，驾崩之年也在永安宫。翠羽华盖只能在空山里想象，玉殿虚无、只存在于野寺之中。古庙的杉松上水鹤筑巢，逢年过节、村翁前来祭祀。武侯祠堂常常就在附近，君臣一体、祭祀也相同。",
