    gradeGroup: "卷六 七言律诗",
    text: "诸葛大名垂宇宙，宗臣遗像肃清高。\n三分割据纡筹策，万古云霄一羽毛。\n伯仲之间见伊吕，指挥若定失萧曹。\n运移汉祚终难复，志决身歼军务劳。",
    translation: "诸葛亮的大名垂于宇宙，宗臣的遗像肃穆清高。三分割据、曲折地施展谋略，万古云霄中他如一片羽毛般高标。与伊尹吕尚相比也不相上下，指挥若定、使萧何曹参也失色。时运转移、汉朝的国祚终究难以恢复，志向坚定、以身殉国、军务劳瘁。",
