    text: "汀洲无浪复无烟，楚客相思益渺然。\n汉口夕阳斜渡鸟，洞庭秋水远连天。\n孤城背岭寒吹角，独戍临江夜泊船。\n贾谊上书忧汉室，长沙谪去古今怜。",
