    author: "钱起",
    gradeGroup: "卷六 七言律诗",
    text: "二月黄鹂飞上林，春城紫禁晓阴阴。\n长乐钟声花外尽，龙池柳色雨中深。\n阳和不散穷途恨，霄汉常悬捧日心。\n献赋十年犹未遇，羞将白发对华簪。",
    translation: "二月里黄鹂飞上林苑，春日的紫禁城清晨阴阴。长乐宫的钟声在花外消尽，龙池的柳色在雨中更深。和暖的阳气驱不散穷途的怨恨，云霄之中常悬着捧日之心。献赋十年仍未遇合，羞于带着白发去面对华簪。",
