    author: "韩翃",
    gradeGroup: "卷六 七言律诗",
    text: "仙台初见五城楼，风物凄凄宿雨收。\n山色遥连秦树晚，砧声近报汉宫秋。\n疏松影落空坛静，细草香闲小洞幽。\n何用别寻方外去，人间亦自有丹丘。",
    translation: "在仙台初次见到五城楼，风物凄清、宿雨刚收。山色远远连着秦地的树、已近傍晚，砧声传来、近报汉宫的秋意。稀疏的松影落在空坛上、一片寂静，细草的清香闲淡、小洞清幽。何必到别处去寻找方外之地，人间也自有丹丘仙境。",
    translationSource: "public-domain",
