    dynasty: "唐",
    author: "柳宗元",
    gradeGroup: "卷六 七言律诗",
    text: "城上高楼接大荒，海天愁思正茫茫。\n惊风乱飐芙蓉水，密雨斜侵薜荔墙。\n岭树重遮千里目，江流曲似九回肠。\n共来百越文身地，犹自音书滞一乡。",
    translation: "城上的高楼连接着荒远之地，海天般的愁思正茫茫无边。狂风胡乱吹动芙蓉池水，密雨斜斜地打湿薜荔墙。岭上的树木重重遮蔽了望远的视线，江流曲折好似九回肠。我们一同来到百越文身之地，却仍然音信阻隔在一方。",
    translationSource: "public-domain",
