    dynasty: "唐",
    author: "元稹",
    gradeGroup: "卷六 七言律诗",
    text: "昔日戏言身后意，今朝都到眼前来。\n衣裳已施行看尽，针线犹存未忍开。\n尚想旧情怜婢仆，也曾因梦送钱财。\n诚知此恨人人有，贫贱夫妻百事哀。",
