    author: "李商隐",
    gradeGroup: "卷六 七言律诗",
    text: "昨夜星辰昨夜风，画楼西畔桂堂东。\n身无彩凤双飞翼，心有灵犀一点通。\n隔座送钩春酒暖，分曹射覆蜡灯红。\n嗟余听鼓应官去，走马兰台类转蓬。",
    translation: "昨夜的星辰、昨夜的风，画楼的西畔、桂堂的东边。我身上没有彩凤那样双飞的翅膀，心里却像灵犀一点相通。隔着座位玩送钩、春酒正暖，分组玩射覆、蜡灯正红。可叹我听到更鼓就要去应差，骑马去兰台、像飘转的飞蓬。",
