    gradeGroup: "卷六 七言律诗",
    text: "紫泉宫殿锁烟霞，欲取芜城作帝家。\n玉玺不缘归日角，锦帆应是到天涯。\n于今腐草无萤火，终古垂杨有暮鸦。\n地下若逢陈后主，岂宜重问后庭花。",
    translation: "紫泉的宫殿锁住了烟霞，他却想拿芜城作为帝王的都城。若不是玉玺归于日角龙颜的李渊，他的锦帆恐怕会一直到天涯。如今腐草间已没有萤火，终古以来垂杨上只有暮鸦。地下若遇见陈后主，难道还好意思再问《后庭花》吗。",
