    source: "《唐诗三百首》",
    dynasty: "唐",
    author: "李商隐",
    gradeGroup: "卷六 七言律诗",
    text: "来是空言去绝踪，月斜楼上五更钟。\n梦为远别啼难唤，书被催成墨未浓。\n蜡照半笼金翡翠，麝熏微度绣芙蓉。\n刘郎已恨蓬山远，更隔蓬山一万重。",
    translation: "你说来只是空话、离去便无踪影，月斜楼上、已响起五更的钟。梦中因为远别而啼哭、难以唤醒，书信被催促写成、墨汁还未磨浓。烛光半笼着金翡翠的帷帐，麝香微微透过绣着芙蓉的被褥。刘郎已经怨恨蓬山遥远，何况更隔着蓬山一万重。",
