    gradeGroup: "卷六 七言律诗",
    text: "飒飒东风细雨来，芙蓉塘外有轻雷。\n金蟾啮锁烧香入，玉虎牵丝汲井回。\n贾氏窥帘韩掾少，宓妃留枕魏王才。\n春心莫共花争发，一寸相思一寸灰。",
    translation: "飒飒的东风挟着细雨而来，芙蓉塘外传来轻轻的雷声。金蟾咬着锁钮、香烟由此而入，玉虎牵着丝绳、从井里汲水回来。贾氏在帘后窥看年轻的韩掾，宓妃留下枕头、爱慕魏王的才华。春心不要与花争着开放，一寸相思就成了一寸灰烬。",
