    gradeGroup: "卷六 七言律诗",
    text: "猿鸟犹疑畏简书，风云常为护储胥。\n徒令上将挥神笔，终见降王走传车。\n管乐有才真不忝，关张无命欲何如。\n他年锦里经祠庙，梁父吟成恨有余。",
