    gradeGroup: "卷六 七言律诗",
    text: "怅卧新春白袷衣，白门寥落意多违。\n红楼隔雨相望冷，珠箔飘灯独自归。\n远路应悲春晼晚，残宵犹得梦依稀。\n玉珰缄札何由达，万里云罗一雁飞。",
    translation: "新春里惆怅地卧着、穿着白色夹衣，白门寥落、心意多有不合。隔着雨望那红楼、只觉清冷，珠帘飘着灯光、我独自归去。远路之上应为春暮而悲伤，残夜之中还能依稀入梦。玉珰与书信怎样才能送到，万里云天如罗、一只大雁飞过。",
