    gradeGroup: "卷六 七言律诗",
    text: "澹然空水对斜晖，曲岛苍茫接翠微。\n波上马嘶看棹去，柳边人歇待船归。\n数丛沙草群鸥散，万顷江田一鹭飞。\n谁解乘舟寻范蠡，五湖烟水独忘机。",
    translation: "空阔的水面淡然对着斜阳，曲折的岛屿苍茫接着青翠的山色。波浪上马在嘶鸣、看船桨划去，柳边有人歇息、等待船回来。几丛沙草、群鸥惊散，万顷江田、一只白鹭飞翔。谁能懂得乘舟去寻访范蠡，在五湖的烟水中独自忘掉机心。",
