    gradeGroup: "卷六 七言律诗",
    text: "苏武魂销汉使前，古祠高树两茫然。\n云边雁断胡天月，陇上羊归塞草烟。\n回日楼台非甲帐，去时冠剑是丁年。\n茂陵不见封侯印，空向秋波哭逝川。",
    translation: "苏武在汉使面前神魂震撼，古祠与高树都一片茫然。云边的雁影断绝在胡天的月下，陇上的羊群归来在塞草的烟雾中。回来时楼台已经不是当年的甲帐，离去时加冠佩剑正当壮年。汉武帝已看不到他封侯的印绶，只能空对着秋水哀哭逝去的岁月。",
