    author: "李白",
    gradeGroup: "卷七 五言绝句",
    text: "美人卷珠帘，深坐颦蛾眉。\n但见泪痕湿，不知心恨谁。",
    translation: "美人卷起珠帘，久坐皱眉。只见她泪痕沾湿，却不知她心里怨恨的是谁。",
