    text: "鸣筝金粟柱，素手玉房前。\n欲得周郎顾，时时误拂弦。",
    translation: "金粟装饰的筝柱发出鸣响，洁白的手弹在玉房之前。想得到周郎那样的顾盼，便时时故意弹错琴弦。",
    translationSource: "public-domain",
