    gradeGroup: "卷七 五言绝句",
    text: "三日入厨下，洗手作羹汤。\n未谙姑食性，先遣小姑尝。",
    translation: "婚后三天走进厨房，洗净手做羹汤。不知道婆婆的口味，先让小姑尝一尝。",
    translationSource: "public-domain",
