    gradeGroup: "卷七 五言绝句",
    text: "寥落古行宫，宫花寂寞红。\n白头宫女在，闲坐说玄宗。",
    translation: "寥落的古老行宫，宫中的花寂寞地红着。白头宫女还在这里，闲坐谈论着玄宗。",
