    gradeGroup: "卷七 五言绝句",
    text: "绿蚁新醅酒，红泥小火炉。\n晚来天欲雪，能饮一杯无。",
    translation: "新酿的酒上浮着绿色的泡沫，红泥做的小火炉。傍晚天要下雪了，能来喝一杯吗。",
