    author: "张祜",
    gradeGroup: "卷七 五言绝句",
    text: "故国三千里，深宫二十年。\n一声何满子，双泪落君前。",
    translation: "故乡远在三千里之外，深宫里已过了二十年。唱一声《何满子》，双泪落在君王面前。",
