    gradeGroup: "卷七 五言绝句",
    text: "向晚意不适，驱车登古原。\n夕阳无限好，只是近黄昏。",
    translation: "傍晚时心情不畅，驱车登上古老的乐游原。夕阳无限美好，只是已经接近黄昏。",
