    author: "李频",
    gradeGroup: "卷七 五言绝句",
    text: "岭外音书绝，经冬复立春。\n近乡情更怯，不敢问来人。",
    translation: "岭外与家乡的音信断绝，过了冬天又到立春。越靠近家乡、心情越是怯怯，不敢询问从家乡来的人。",
    translationSource: "public-domain",
