    gradeGroup: "卷七 五言绝句",
    text: "打起黄莺儿，莫教枝上啼。\n啼时惊妾梦，不得到辽西。",
    translation: "赶走那黄莺儿，不要让它在枝上啼叫。它啼叫时惊醒了我的梦，使我不能在梦中到辽西。",
