    gradeGroup: "卷八 七言绝句",
    text: "离别家乡岁月多，近来人事半消磨。\n惟有门前镜湖水，春风不改旧时波。",
    translation: "离别家乡的岁月已经很多，近来人事多半消磨改变。只有门前镜湖的水，春风吹过还是旧时的波澜。",
