    gradeGroup: "卷八 七言绝句",
    text: "隐隐飞桥隔野烟，石矶西畔问渔船。\n桃花尽日随流水，洞在清溪何处边。",
    translation: "隐隐约约的飞桥隔着野外的烟雾，在石矶的西边询问渔船。桃花整日随着流水漂去，那桃花洞在清溪的哪一边呢。",
