    title: "送孟浩然之广陵",
    source: "《唐诗三百首》",
    dynasty: "唐",
    author: "李白",
    gradeGroup: "卷八 七言绝句",
    text: "故人西辞黄鹤楼，烟花三月下扬州。\n孤帆远影碧空尽，惟见长江天际流。",
    translation: "老朋友在西边辞别黄鹤楼，烟花三月里顺流去扬州。孤帆的远影消失在碧空尽头，只见长江向天边流去。",
    translationSource: "public-domain",
