/* 索引：按 id 查、按卷查 */
(function () {
  window.TANGSHI_ALL = window.POEMS_TANGSHI;
  window.getTangshiById = function (id) {
    return window.POEMS_TANGSHI.filter(function (p) { return p.id === id; })[0] || null;
  };
  window.getTangshiGroups = function () {
    var groups = [];
    window.POEMS_TANGSHI.forEach(function (p) {
      var g = p.gradeGroup || "其他";
      var hit = groups.filter(function (it) { return it.name === g; })[0];
      if (!hit) { hit = { name: g, items: [] }; groups.push(hit); }
      hit.items.push(p);
    });
    return groups;
  };
})();
